/// <summary>
///     The <c>AVACustFreeInvoiceFrm_CustInvoiceTableDS_AVABonusAllocationBaseFld_Extension</c> class is the extension for <c>CustFreeInvoice</c>
/// </summary>
[ExtensionOf(formDataFieldStr(CustFreeInvoice, CustInvoiceTable, AVABonusAllocationBase))]
public final class AVACustFreeInvoiceFrm_CustInvoiceTableDS_AVABonusAllocationBaseFld_Extension
{
}

Method.Source:
/// <summary>
///     AVA <c>modified</c> method.
/// </summary>
public void modified()
{
    CustInvoiceTable    locCustInvoiceTable;
    FormControl         locFC_AVABonusAlliance;
    FormControl         locFC_AVABonusCustAccount;
    boolean             locAllowEdit_AVABonusAlliance;

    next modified();

    locCustInvoiceTable = element.dataSource(tableStr(CustInvoiceTable)).cursor();

    if(locCustInvoiceTable.AVABonusAllocationBase == AVABonusAllocationBase::Customer)
    {
        locAllowEdit_AVABonusAlliance = false;
    }
    else if(locCustInvoiceTable.AVABonusAllocationBase == AVABonusAllocationBase::Alliance)
    {
        locAllowEdit_AVABonusAlliance = true;
    }
    locFC_AVABonusAlliance     = element.design().controlName(formControlStr(CustFreeInvoice, FormGroupCVHeaderFastTab_BonusFields_AVABonusAlliance));
    locFC_AVABonusAlliance.allowEdit(locAllowEdit_AVABonusAlliance);
    locFC_AVABonusAlliance     = element.design().controlName(formControlStr(CustFreeInvoice, FastTabGroup_BonusFields_AVABonusAlliance));
    locFC_AVABonusAlliance.allowEdit(locAllowEdit_AVABonusAlliance);

    locFC_AVABonusCustAccount     = element.design().controlName(formControlStr(CustFreeInvoice, FormGroupCVHeaderFastTab_BonusFields_AVABonusCustAccount));
    locFC_AVABonusCustAccount.allowEdit(!locAllowEdit_AVABonusAlliance);
    locFC_AVABonusCustAccount     = element.design().controlName(formControlStr(CustFreeInvoice, FastTabGroup_BonusFields_AVABonusCustAccount));
    locFC_AVABonusCustAccount.allowEdit(!locAllowEdit_AVABonusAlliance);
}
